function sortDigitsInPlace(arr){
  const count = new Array(10).fill(0);
  for (let v of arr) count[v]++;
  let i = 0;
  for (let d = 0; d <= 9; d++){
    for (let c = 0; c < count[d]; c++) arr[i++] = d;
